FontCache* FontCache::forCurrentThreadIfExists()
{
#if PLATFORM(DIHOS)
    // Main-thread TLS is finalized before process static destructors. Font
    // destructors must not resurrect ThreadGlobalData (and its shared timer).
    auto* thread = Thread::currentMayBeNull();
    if (!thread || !thread->m_clientData)
        return nullptr;
    return downcast<ThreadGlobalData>(*thread->m_clientData).fontCacheIfExists();
#else
    return threadGlobalDataSingleton().fontCacheIfExists();
#endif
}

FontCache* FontCache::forCurrentThreadIfNotDestroyed()
{
#if PLATFORM(DIHOS)
    // Main-thread TLS is finalized before process static destructors. Font
    // destructors must not resurrect ThreadGlobalData (and its shared timer).
    auto* thread = Thread::currentMayBeNull();
    if (!thread || !thread->m_clientData)
        return nullptr;
    return downcast<ThreadGlobalData>(*thread->m_clientData).fontCacheIfNotDestroyed();
#else
    return threadGlobalDataSingleton().fontCacheIfNotDestroyed();
#endif
}

